import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"管理后台一览","description":"","frontmatter":{},"headers":[],"relativePath":"admin/console.md","filePath":"admin/console.md"}'),o={name:"admin/console.md"};function l(i,t,n,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="管理后台一览" tabindex="-1">管理后台一览 <a class="header-anchor" href="#管理后台一览" aria-label="Permalink to &quot;管理后台一览&quot;">​</a></h1><p>浏览器打开服务端的 <code>/admin</code>，用管理员账号登录。</p><table tabindex="0"><thead><tr><th>页面</th><th>作用</th></tr></thead><tbody><tr><td>仪表盘</td><td>设备、用量、拦截记录概览；用量可以按模型（含缓存命中率）、按用途（正常对话、压缩上下文、任务复盘、整理记忆、生成标题等后台调用）分开看</td></tr><tr><td>设备列表</td><td>所有电脑的在线和资产信息；编辑使用者、部门（从部门清单里选）、备注；停用某台；向某台电脑远程下发指令；详情里看这台电脑能用的技能 / 专家 / 连接器，单独设置安全中心的项</td></tr><tr><td>部门</td><td>部门清单（改名会同步到设备和使用范围；还在用的部门不能删）；每个部门单独设置安全中心的项</td></tr><tr><td>指令中心</td><td>远程指令的下发、进度、结果；指令模板</td></tr><tr><td>安全中心</td><td>见 <a href="./security-center.html">安全中心</a></td></tr><tr><td>技能库</td><td>新建技能（手写或 AI 起草）、导入、编辑、标记必装</td></tr><tr><td>专家</td><td>建专家（可以让 AI 按一句话起草）、草稿 / 发布 / 下线、历史版本回滚、派遣记录</td></tr><tr><td>MCP 连接器</td><td>引入厂商的连接器、写介绍和示例、统一预填密钥、试连、上下架</td></tr><tr><td>插件</td><td>按部门下发一组技能、专家、连接器、快捷指令、工具规则</td></tr><tr><td>快捷指令</td><td>发布全公司通用的 <code>/</code> 指令</td></tr><tr><td>事件触发</td><td>外部系统推送事件后，在指定电脑上开任务（默认关、默认只预演）</td></tr><tr><td>员工端版本</td><td>上传、发布新版本；下载安装包</td></tr><tr><td>配额与用量</td><td>全局和单台电脑的每日 token 上限、用量排行</td></tr><tr><td>审计</td><td>每一次工具调用（含拦截、拒绝），记录来源（聊天窗口、命令行、IDE、专家）和任务编号；可按任务编号筛选、导出，同一件事跨好几轮的操作一次看全</td></tr><tr><td>意见反馈</td><td>员工提交的问题和日志</td></tr><tr><td>协议与隐私</td><td>修改用户协议和隐私政策</td></tr></tbody></table><h2 id="账号与权限" tabindex="-1">账号与权限 <a class="header-anchor" href="#账号与权限" aria-label="Permalink to &quot;账号与权限&quot;">​</a></h2><p>后台账号是具名的，可以分别授权：</p><ul><li>能不能查看聊天内容（查看会记入访问记录）；</li><li>能不能远程下发指令；</li><li>超级管理员才能管理账号和部分全局开关。</li></ul><p>共享的管理员令牌只用于命令行脚本，不能查看聊天内容、不能下发指令。</p><h2 id="按部门隔离" tabindex="-1">按部门隔离 <a class="header-anchor" href="#按部门隔离" aria-label="Permalink to &quot;按部门隔离&quot;">​</a></h2><p>技能、专家、MCP 连接器都有「<strong>使用范围</strong>」：选哪些部门、另外哪几台电脑能用。</p><ul><li>不选 = 全公司都能用（已有的条目升级后就是这样，行为不变）；</li><li>范围由服务端执行：范围外的电脑在员工端看不到，按名字直接下载技能包、使用或派遣专家也会被拒绝；连接器里 IT 预填的公共账号只下发给范围内的电脑；</li><li>收回范围（或电脑换了部门）后，员工端几秒内同步：之前从技能库装的技能被删掉、连接器断开、专家从列表消失；</li><li>插件带来的技能 / 专家 / 连接器，要同时在插件的下发部门和条目自己的范围里。</li></ul><p>例如：考勤技能、考勤专家、考勤连接器都把范围设成「行政部」，只有行政部的电脑能用。</p>',11)])])}const m=d(o,[["render",l]]);export{_ as __pageData,m as default};
